package main

import _ "embed"

// The tray icon is embedded so the binary is self-contained — a wrapper that
// loaded its icon from disk would show a blank tray slot if the file were missing,
// which looks broken in the one place the user always sees.
//
// Generated by scripts/build/make-icon.mjs, which writes it here as well as to
// installer/ — go:embed cannot reference a path outside the module directory. Run
// `npm run icon` if it is missing.
//
//go:embed logo.ico
var trayIconICO []byte

// Status colouring is done with the same glyph rather than four separate icons:
// the tray reflects state through its tooltip and menu text, and one recognisable
// mark beats four near-identical ones the user has to squint at.
func trayIcon() []byte { return trayIconICO }
